function HardyLab(){const [p,setP]=useState(.6),[selection,setSelection]=useState(.15),[generations,setGenerations]=useState(30);const genotype=hardyWeinberg(p),history=selectedPopulation(p,selection,generations);
 return <Frame info={{title:'Hardy–Weinberg and natural selection',detail:'Start from an allele frequency, inspect ideal genotype proportions, then apply an illustrative fitness difference across generations.',limitation:'Assumes a single locus, random mating and deterministic selection, with genotype relative fitness AA=1, Aa=1−s/2, aa=1−s. No migration, mutation, finite-population drift or genetic linkage.'}} metrics={[{label:'AA',value:`${(genotype.AA*100).toFixed(1)}%`},{label:'Aa',value:`${(genotype.Aa*100).toFixed(1)}%`},{label:'aa',value:`${(genotype.aa*100).toFixed(1)}%`},{label:'Final A frequency',value:history.at(-1)!.p.toFixed(3)}]}>
 <Controls><Slider name="Initial A allele frequency (p)" value={p} onChange={setP} min={.05} max={.95} step={.01}/><Slider name="Selection strength (s)" value={selection} onChange={setSelection} min={0} max={.8} step={.01}/><Slider name="Generations" value={generations} onChange={setGenerations} min={1} max={100} unit="gen"/><p className="advanced-hint">Without evolutionary forces, p² + 2pq + q² = 1.</p></Controls>
 <Scene caption="The line shows allele frequency across generations under the stated fitness model."><Curve data={history.map(h=>h.p)} min={0} max={1}/><div className="advanced-genotypes">{[['AA',genotype.AA],['Aa',genotype.Aa],['aa',genotype.aa]].map(([label,value])=><div key={String(label)} style={{flex:Number(value)}}><b>{label}</b><small>{(Number(value)*100).toFixed(0)}%</small></div>)}</div></Scene>
 </Frame>;
}
